def subtract(a, b):
    # Filter out empty intervals and sort
    a = sorted([interval for interval in a if interval[0] < interval[1]])
    b = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a:
        return []

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # For each interval in a, subtract all intervals in b
    result = []

    for a_start, a_end in a:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep parts outside b
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result.sort()
    merged = [result[0]]
    for start, end in result[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

